41	 * Space balanced block placement policy.
42	 */
43	public class AvailableSpaceBlockPlacementPolicy extends
44	    BlockPlacementPolicyDefault {
45	  private static final Logger LOG = LoggerFactory
46	      .getLogger(AvailableSpaceBlockPlacementPolicy.class);
47	  private static final Random RAND = new Random();
48	  private int balancedPreference =
49	      (int) (100 * DFS_NAMENODE_AVAILABLE_SPACE_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_DEFAULT);
50	  private boolean optimizeLocal;
51	
52	  @Override
53	  public void initialize(Configuration conf, FSClusterStats stats,
54	      NetworkTopology clusterMap, Host2NodesMap host2datanodeMap) {
55	    super.initialize(conf, stats, clusterMap, host2datanodeMap);
56	    float balancedPreferencePercent =
57	        conf.getFloat(
58	          DFS_NAMENODE_AVAILABLE_SPACE_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_KEY,
59	          DFS_NAMENODE_AVAILABLE_SPACE_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_DEFAULT);
60	
61	    LOG.info("Available space block placement policy initialized: "
62	        + DFSConfigKeys.DFS_NAMENODE_AVAILABLE_SPACE_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_KEY
63	        + " = " + balancedPreferencePercent);
64	
65	    optimizeLocal = conf.getBoolean(
66	        DFSConfigKeys.DFS_NAMENODE_AVAILABLE_SPACE_BLOCK_PLACEMENT_POLICY_BALANCE_LOCAL_NODE_KEY,
67	        DFSConfigKeys.DFS_NAMENODE_AVAILABLE_SPACE_BLOCK_PLACEMENT_POLICY_BALANCE_LOCAL_NODE_DEFAULT);
68	
69	    if (balancedPreferencePercent > 1.0) {
70	      LOG.warn("The value of "
71	          + DFS_NAMENODE_AVAILABLE_SPACE_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_KEY
72	          + " is greater than 1.0 but should be in the range 0.0 - 1.0");
73	    }
74	    if (balancedPreferencePercent < 0.5) {
75	      LOG.warn("The value of "
76	          + DFS_NAMENODE_AVAILABLE_SPACE_BLOCK_PLACEMENT_POLICY_BALANCED_SPACE_PREFERENCE_FRACTION_KEY
77	          + " is less than 0.5 so datanodes with more used percent will"
78	          + " receive  more block allocations.");
79	    }
80	    balancedPreference = (int) (100 * balancedPreferencePercent);
81	  }
