83	  @Override
84	  protected DatanodeDescriptor chooseDataNode(final String scope,
85	      final Collection<Node> excludedNode, StorageType type) {
86	    // only the code that uses DFSNetworkTopology should trigger this code path.
87	    Preconditions.checkArgument(clusterMap instanceof DFSNetworkTopology);
88	    DFSNetworkTopology dfsClusterMap = (DFSNetworkTopology)clusterMap;
89	    DatanodeDescriptor a = (DatanodeDescriptor) dfsClusterMap
90	        .chooseRandomWithStorageTypeTwoTrial(scope, excludedNode, type);
91	    DatanodeDescriptor b = (DatanodeDescriptor) dfsClusterMap
92	        .chooseRandomWithStorageTypeTwoTrial(scope, excludedNode, type);
93	    return select(a, b, false);
94	  }
