96	  @Override
97	  protected DatanodeStorageInfo chooseLocalStorage(Node localMachine,
98	      Set<Node> excludedNodes, long blocksize, int maxNodesPerRack,
99	      List<DatanodeStorageInfo> results, boolean avoidStaleNodes,
100	      EnumMap<StorageType, Integer> storageTypes, boolean fallbackToLocalRack)
101	      throws NotEnoughReplicasException {
102	    if (!optimizeLocal) {
103	      return super.chooseLocalStorage(localMachine, excludedNodes, blocksize,
104	          maxNodesPerRack, results, avoidStaleNodes, storageTypes,
105	          fallbackToLocalRack);
106	    }
107	    final EnumMap<StorageType, Integer> initialStorageTypesLocal =
108	        storageTypes.clone();
109	    final EnumMap<StorageType, Integer> initialStorageTypesLocalRack =
110	        storageTypes.clone();
111	    DatanodeStorageInfo local =
112	        chooseLocalStorage(localMachine, excludedNodes, blocksize,
113	            maxNodesPerRack, results, avoidStaleNodes,
114	            initialStorageTypesLocal);
115	    if (!fallbackToLocalRack) {
116	      return local;
117	    }
118	    if (local != null) {
119	      results.remove(local);
120	    }
121	    DatanodeStorageInfo localRack =
122	        chooseLocalRack(localMachine, excludedNodes, blocksize, maxNodesPerRack,
123	            results, avoidStaleNodes, initialStorageTypesLocalRack);
124	    if (local != null && localRack != null) {
125	      if (select(local.getDatanodeDescriptor(),
126	          localRack.getDatanodeDescriptor(), true) == local
127	          .getDatanodeDescriptor()) {
128	        results.remove(localRack);
129	        results.add(local);
130	        swapStorageTypes(initialStorageTypesLocal, storageTypes);
131	        excludedNodes.remove(localRack.getDatanodeDescriptor());
132	        return local;
133	      } else {
134	        swapStorageTypes(initialStorageTypesLocalRack, storageTypes);
135	        excludedNodes.remove(local.getDatanodeDescriptor());
136	        return localRack;
137	      }
138	    } else if (localRack == null && local != null) {
139	      results.add(local);
140	      swapStorageTypes(initialStorageTypesLocal, storageTypes);
141	      return local;
142	    } else {
143	      swapStorageTypes(initialStorageTypesLocalRack, storageTypes);
144	      return localRack;
145	    }
146	  }
147	
148	  private void swapStorageTypes(EnumMap<StorageType, Integer> fromStorageTypes,
149	      EnumMap<StorageType, Integer> toStorageTypes) {
150	    toStorageTypes.clear();
151	    toStorageTypes.putAll(fromStorageTypes);
152	  }
153	
154	  @Override
155	  protected DatanodeDescriptor chooseDataNode(final String scope,
156	      final Collection<Node> excludedNode) {
157	    DatanodeDescriptor a =
158	        (DatanodeDescriptor) clusterMap.chooseRandom(scope, excludedNode);
159	    DatanodeDescriptor b =
160	        (DatanodeDescriptor) clusterMap.chooseRandom(scope, excludedNode);
161	    return select(a, b, false);
162	  }
163	
164	  private DatanodeDescriptor select(DatanodeDescriptor a, DatanodeDescriptor b,
165	      boolean isBalanceLocal) {
166	    if (a != null && b != null){
167	      int ret = compareDataNode(a, b, isBalanceLocal);
168	      if (ret == 0) {
169	        return a;
170	      } else if (ret < 0) {
171	        return (RAND.nextInt(100) < balancedPreference) ? a : b;
172	      } else {
173	        return (RAND.nextInt(100) < balancedPreference) ? b : a;
174	      }
175	    } else {
176	      return a == null ? b : a;
177	    }
178	  }
179	
180	  /**
181	   * Compare the two data nodes.
182	   */
183	  protected int compareDataNode(final DatanodeDescriptor a,
184	      final DatanodeDescriptor b, boolean isBalanceLocal) {
185	    if (a.equals(b)
186	        || Math.abs(a.getDfsUsedPercent() - b.getDfsUsedPercent()) < 5 || ((
187	        isBalanceLocal && a.getDfsUsedPercent() < 50))) {
188	      return 0;
189	    }
190	    return a.getDfsUsedPercent() < b.getDfsUsedPercent() ? -1 : 1;
191	  }
192	}

